const items = $input.all();

const validContacts = [];
const invalidContacts = [];

for (const item of items) {
  const contact = item.json;
  const errors = [];

  // Rule 1: First name is required
  if (!contact.firstName) {
    errors.push("Missing first name");
  }

  // Rule 2: Last name is required
  if (!contact.lastName) {
    errors.push("Missing last name");
  }

  // Rule 3: Email is required
  if (!contact.email) {
    errors.push("Missing email");
  } else {
    // Rule 4: Email must have a basic valid structure
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

    if (!emailRegex.test(contact.email)) {
      errors.push("Invalid email format");
    }
  }

  // Rule 5: Phone is optional, but if provided, validate it
  if (contact.phone) {
    const phoneDigits = contact.phone.replace(/\D/g, "");

    if (phoneDigits.length < 7 || phoneDigits.length > 15) {
      errors.push("Invalid phone number length");
    }
  }

  const validatedContact = {
    ...contact,
    isValid: errors.length === 0,
    validationErrors: errors,
    validationStatus: errors.length === 0 ? "VALID" : "INVALID",
  };

  if (validatedContact.isValid) {
    validContacts.push(validatedContact);
  } else {
    invalidContacts.push(validatedContact);
  }
}

return [
  {
    json: {
      totalProcessed: items.length,
      validCount: validContacts.length,
      invalidCount: invalidContacts.length,
      validContacts,
      invalidContacts,
    },
  },
];

const items = $input.all();

function getValue(value) {
  if (value === null || value === undefined) return "";
  if (typeof value === "object" && value.value !== undefined) {
    return value.value ?? "";
  }
  return value;
}

function getField(contact, fieldNames) {
  const properties = contact.properties || {};

  for (const field of fieldNames) {
    const value = getValue(properties[field] ?? contact[field]);

    if (value !== null && value !== undefined && String(value).trim() !== "") {
      return String(value).trim();
    }
  }

  return "";
}

function normalizeName(value) {
  return String(value || "")
    .trim()
    .replace(/\s+/g, " ")
    .toLowerCase()
    .replace(/\b\w/g, char => char.toUpperCase());
}

function normalizeEmail(value) {
  return String(value || "")
    .trim()
    .toLowerCase();
}

function normalizePhone(value) {
  const raw = String(value || "").trim();

  if (!raw) return "";

  const hasPlus = raw.startsWith("+");
  const digits = raw.replace(/\D/g, "");

  return hasPlus ? `+${digits}` : digits;
}

function normalizeCompany(value) {
  return String(value || "")
    .trim()
    .replace(/\s+/g, " ");
}

return items.map(item => {
  const contact = item.json;

  const firstName = getField(contact, ["firstname", "firstName"]);
  const lastName = getField(contact, ["lastname", "lastName"]);
  const email = getField(contact, ["email", "email", "work_email"]);
  const phone = getField(contact, ["phone", "phone", "phone"]);
  const company = getField(contact, ["company"]);
  const jobTitle = getField(contact, ["jobtitle", "jobTitle"]);
  const lifecycleStage = getField(contact, ["lifecyclestage", "lifecycleStage"]);

  return {
    json: {
      hubspotId: contact.vid ?? contact.id ?? "",
      firstName: normalizeName(firstName),
      lastName: normalizeName(lastName),
      email: normalizeEmail(email),
      phone: normalizePhone(phone),
      company: normalizeCompany(company),
      jobTitle: String(jobTitle || "").trim(),
      lifecycleStage: String(lifecycleStage || "").trim(),
    }
  };
});

const input = $input.first().json;
const contacts = input.validContacts || [];

const emailGroups = {};
const phoneGroups = {};

function normalizePhoneForMatch(phone) {
  let digits = String(phone || "").replace(/\D/g, "");

  // For this test dataset, treat India's +91 prefix
  // and a 10-digit Indian number as equivalent.
  if (digits.length === 12 && digits.startsWith("91")) {
    digits = digits.slice(2);
  }

  return digits;
}

// 1. Build matching groups
for (const contact of contacts) {
  const email = String(contact.email || "").trim().toLowerCase();

  const phone = normalizePhoneForMatch(contact.phone);

  if (email) {
    if (!emailGroups[email]) {
      emailGroups[email] = [];
    }

    emailGroups[email].push(contact);
  }

  if (phone) {
    if (!phoneGroups[phone]) {
      phoneGroups[phone] = [];
    }

    phoneGroups[phone].push(contact);
  }
}

// 2. Identify duplicate groups
const duplicateGroups = [];
const duplicateContactIds = new Set();
const duplicateReasons = {};

function recordDuplicateGroup(type, key, group) {
  if (group.length < 2) return;

  const ids = group.map(contact => contact.hubspotId);

  duplicateGroups.push({
    matchType: type,
    matchKey: key,
    count: group.length,
    contacts: group.map(contact => ({
      hubspotId: contact.hubspotId,
      firstName: contact.firstName,
      lastName: contact.lastName,
      email: contact.email,
      phone: contact.phone,
      company: contact.company
    }))
  });

  for (const contact of group) {
    duplicateContactIds.add(contact.hubspotId);

    if (!duplicateReasons[contact.hubspotId]) {
      duplicateReasons[contact.hubspotId] = [];
    }

    duplicateReasons[contact.hubspotId].push({
      type,
      matchedContactIds: ids.filter(id => id !== contact.hubspotId)
    });
  }
}

for (const [email, group] of Object.entries(emailGroups)) {
  recordDuplicateGroup("EXACT_EMAIL", email, group);
}

for (const [phone, group] of Object.entries(phoneGroups)) {
  recordDuplicateGroup("PHONE_MATCH", phone, group);
}

// 3. Attach duplicate flags to every contact
const reviewedContacts = contacts.map(contact => ({
  ...contact,
  isDuplicate: duplicateContactIds.has(contact.hubspotId),
  duplicateReasons: duplicateReasons[contact.hubspotId] || []
}));

// 4. Separate flagged and unflagged records
const duplicateContacts = reviewedContacts.filter(contact => contact.isDuplicate);
const uniqueContacts = reviewedContacts.filter(contact => !contact.isDuplicate);

return [
  {
    json: {
      totalContacts: contacts.length,
      uniqueCount: uniqueContacts.length,
      flaggedDuplicateCount: duplicateContacts.length,
      duplicateGroupCount: duplicateGroups.length,
      uniqueContacts,
      duplicateContacts,
      duplicateGroups
    }
  }
];

// Collect all records
const input = $input.first().json;

const contacts = [
  ...(input.uniqueContacts || []),
  ...(input.duplicateContacts || [])
];

// 1. Normalize text before comparing
function normalizeText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "");
}

// 2. Calculate Levenshtein edit distance
function levenshtein(a, b) {
  const rows = a.length + 1;
  const cols = b.length + 1;

  const matrix = Array.from({ length: rows }, () =>
    Array(cols).fill(0)
  );

  for (let i = 0; i < rows; i++) {
    matrix[i][0] = i;
  }

  for (let j = 0; j < cols; j++) {
    matrix[0][j] = j;
  }

  for (let i = 1; i < rows; i++) {
    for (let j = 1; j < cols; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;

      matrix[i][j] = Math.min(
        matrix[i - 1][j] + 1,
        matrix[i][j - 1] + 1,
        matrix[i - 1][j - 1] + cost
      );
    }
  }

  return matrix[rows - 1][cols - 1];
}

// 3. Convert edit distance to similarity percentage
function similarity(a, b) {
  if (!a || !b) return 0;

  const distance = levenshtein(a, b);
  const maxLength = Math.max(a.length, b.length);

  return Math.round((1 - distance / maxLength) * 100);
}

// 4. Compare every contact against every other contact
const fuzzyCandidates = [];
const comparedPairs = new Set();

const NAME_THRESHOLD = 85;
const COMPANY_THRESHOLD = 75;

for (let i = 0; i < contacts.length; i++) {
  for (let j = i + 1; j < contacts.length; j++) {
    const contactA = contacts[i];
    const contactB = contacts[j];

    // Avoid comparing the same contact with itself
    if (contactA.hubspotId === contactB.hubspotId) {
      continue;
    }

    // Prevent duplicate pair comparisons
    const pairKey = [
      contactA.hubspotId,
      contactB.hubspotId
    ].sort().join("_");

    if (comparedPairs.has(pairKey)) {
      continue;
    }

    comparedPairs.add(pairKey);

    const nameA = normalizeText(
      `${contactA.firstName} ${contactA.lastName}`
    );

    const nameB = normalizeText(
      `${contactB.firstName} ${contactB.lastName}`
    );

    const companyA = normalizeText(contactA.company);
    const companyB = normalizeText(contactB.company);

    const nameScore = similarity(nameA, nameB);
    const companyScore = similarity(companyA, companyB);

    // Flag pairs that pass BOTH similarity thresholds
    if (
      nameScore >= NAME_THRESHOLD &&
      companyScore >= COMPANY_THRESHOLD
    ) {
      fuzzyCandidates.push({
        matchType: "FUZZY_NAME_COMPANY",
        nameSimilarity: nameScore,
        companySimilarity: companyScore,
        contacts: [
          {
            hubspotId: contactA.hubspotId,
            fullName: `${contactA.firstName} ${contactA.lastName}`,
            email: contactA.email,
            company: contactA.company
          },
          {
            hubspotId: contactB.hubspotId,
            fullName: `${contactB.firstName} ${contactB.lastName}`,
            email: contactB.email,
            company: contactB.company
          }
        ]
      });
    }
  }
}

// 5. Return results
return [
  {
    json: {
      totalContacts: contacts.length,
      totalPairsCompared: comparedPairs.size,
      fuzzyCandidateCount: fuzzyCandidates.length,
      thresholds: {
        nameSimilarity: NAME_THRESHOLD,
        companySimilarity: COMPANY_THRESHOLD
      },
      fuzzyCandidates
    }
  }
];

const duplicateData = $("De-Dup").first().json;
const fuzzyData = $("Fuzzy Match Engine").first().json;

const contacts = [
  ...(duplicateData.uniqueContacts || []),
  ...(duplicateData.duplicateContacts || [])
];

const contactsById = new Map(
  contacts.map(contact => [
    String(contact.hubspotId),
    contact
  ])
);

const pairMap = new Map();

function addPair(contactAId, contactBId, signal) {
  const idA = String(contactAId);
  const idB = String(contactBId);

  if (!contactsById.has(idA) || !contactsById.has(idB)) {
    return;
  }

  const sortedIds = [idA, idB].sort();
  const pairKey = sortedIds.join("::");

  if (!pairMap.has(pairKey)) {
    pairMap.set(pairKey, {
      contactIds: sortedIds,
      matchSignals: []
    });
  }

  const pair = pairMap.get(pairKey);

  const signalExists = pair.matchSignals.some(
    existing =>
      existing.matchType === signal.matchType &&
      existing.matchKey === signal.matchKey
  );

  if (!signalExists) {
    pair.matchSignals.push(signal);
  }
}

// Add exact email and phone matches
for (const group of duplicateData.duplicateGroups || []) {
  const groupContacts = group.contacts || [];

  for (let i = 0; i < groupContacts.length; i++) {
    for (let j = i + 1; j < groupContacts.length; j++) {
      addPair(
        groupContacts[i].hubspotId,
        groupContacts[j].hubspotId,
        {
          matchType: group.matchType,
          matchKey: group.matchKey
        }
      );
    }
  }
}

// Add fuzzy matches
for (const candidate of fuzzyData.fuzzyCandidates || []) {
  const matchedContacts = candidate.contacts || [];

  if (matchedContacts.length !== 2) continue;

  addPair(
    matchedContacts[0].hubspotId,
    matchedContacts[1].hubspotId,
    {
      matchType: candidate.matchType,
      nameSimilarity: candidate.nameSimilarity,
      companySimilarity: candidate.companySimilarity
    }
  );
}

// Build consolidated pairs
const duplicatePairs = Array.from(pairMap.values()).map(pair => ({
  contactIds: pair.contactIds,
  contacts: pair.contactIds.map(id => contactsById.get(id)),
  matchSignals: pair.matchSignals
}));

// Identify flagged contact IDs
const flaggedIds = new Set();

for (const pair of duplicatePairs) {
  for (const id of pair.contactIds) {
    flaggedIds.add(id);
  }
}

// Review every contact
const reviewedContacts = contacts.map(contact => {
  const contactId = String(contact.hubspotId);

  const relatedPairs = duplicatePairs.filter(pair =>
    pair.contactIds.includes(contactId)
  );

  return {
    ...contact,
    isDuplicate: flaggedIds.has(contactId),
    consolidatedMatchCount: relatedPairs.length,
    consolidatedMatchSignals: relatedPairs.flatMap(
      pair => pair.matchSignals
    )
  };
});

const duplicateContacts = reviewedContacts.filter(
  contact => contact.isDuplicate
);

const uniqueContacts = reviewedContacts.filter(
  contact => !contact.isDuplicate
);

return [
  {
    json: {
      totalContacts: reviewedContacts.length,
      uniqueCount: uniqueContacts.length,
      flaggedDuplicateCount: duplicateContacts.length,
      duplicatePairCount: duplicatePairs.length,
      duplicateContacts,
      uniqueContacts,
      duplicatePairs
    }
  }
];

const result = $("De-Dups Consolidation").first().json;
const validation = $("Contact Validation").first().json;

// 1. Prepare the three datasets
const uniqueContacts = result.uniqueContacts || [];
const duplicateContacts = result.duplicateContacts || [];
const invalidContacts = validation.invalidContacts || [];

// 2. Define the columns we want in our CSV files
const columns = [
  "hubspotId",
  "firstName",
  "lastName",
  "email",
  "phone",
  "company",
  "jobTitle",
  "lifecycleStage"
];

// 3. Keep only the selected columns
function prepareRows(contacts) {
  return contacts.map(contact => {
    const row = {};

    for (const column of columns) {
      row[column] = contact[column] ?? "";
    }

    return row;
  });
}

// 4. Return all three datasets
return [
  {
    json: {
      fileName: "unique_contacts.csv",
      recordCount: uniqueContacts.length,
      rows: prepareRows(uniqueContacts)
    }
  },
  {
    json: {
      fileName: "duplicate_contacts.csv",
      recordCount: duplicateContacts.length,
      rows: prepareRows(duplicateContacts)
    }
  },
  {
    json: {
      fileName: "invalid_contacts.csv",
      recordCount: invalidContacts.length,
      rows: prepareRows(invalidContacts)
    }
  }
];

const dataset = $(".csv Preparation").all()[0].json;

return dataset.rows.map(row => ({
  json: row
}));
